-- Disposable local database only; all synthetic data and test DDL roll back.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions, pg_temp;
select no_plan();
create function pg_temp.affected(statement text) returns integer language plpgsql security invoker as $$
declare n integer; begin execute statement; get diagnostics n = row_count; return n; end; $$;
select is((select count(*)::int from public.exercises where owner_id is null),183,'fresh replay installs 183 system exercises');
select is((select count(*)::int from public.exercises where exercise_type='compound' and owner_id is null),105,'105 compound exercises');
select is((select count(*)::int from public.exercises where exercise_type='isolation' and owner_id is null),63,'63 isolation exercises');
select is((select count(*)::int from public.exercises where exercise_type='other' and owner_id is null),15,'15 other exercises');
select ok(not exists(select 1 from public.exercises where exercise_type not in ('compound','isolation','other') or exercise_type is null),'every exercise has a constrained classification');
select ok(not exists(select slug from public.exercises group by slug having count(*)>1),'canonical slugs are unique');
select ok(not exists(select 1 from public.exercises e where owner_id is null and (select count(*) from public.exercise_movement_patterns p where p.exercise_id=e.id and p.is_primary)<>1),'each system exercise has exactly one primary pattern');
select ok(not exists(select 1 from public.exercises e where owner_id is null and not exists(select 1 from public.exercise_muscles m where m.exercise_id=e.id and m.muscle_role='primary')),'every system exercise has primary muscles');
select ok(not exists(select 1 from public.exercises e where owner_id is null and not exists(select 1 from public.exercise_equipment q where q.exercise_id=e.id)),'equipment requirements are explicit');
select ok(not exists(select 1 from public.exercise_equipment q join public.equipment_types t on t.id=q.equipment_type_id where t.slug='none' and exists(select 1 from public.exercise_equipment x where x.exercise_id=q.exercise_id and x.equipment_type_id<>t.id)),'None is never an equipment alternative in a conjunction');
select ok(not exists(select 1 from public.exercise_movement_patterns x left join public.movement_patterns p on p.id=x.movement_pattern_id where p.id is null),'movement references are valid');
select ok(not exists(select 1 from public.exercise_muscles x left join public.muscle_groups p on p.id=x.muscle_group_id where p.id is null),'muscle references are valid');
select ok(not exists(select 1 from public.exercise_equipment x left join public.equipment_types p on p.id=x.equipment_type_id where p.id is null),'equipment references are valid');
select ok((select not prosecdef and proconfig=array['search_path=""'] from pg_proc where oid='public.save_custom_exercise(uuid,text,text,uuid,uuid[],uuid[],uuid[],uuid[],text)'::regprocedure),'custom editor is invoker with empty search path');
select ok(not has_function_privilege('anon','public.save_custom_exercise(uuid,text,text,uuid,uuid[],uuid[],uuid[],uuid[],text)','execute'),'anonymous RPC execution denied');
select ok(not has_function_privilege('service_role','public.save_custom_exercise(uuid,text,text,uuid,uuid[],uuid[],uuid[],uuid[],text)','execute'),'service role RPC execution not granted');
insert into auth.users(id,email_confirmed_at) values (md5('phase4_alice')::uuid,clock_timestamp()),(md5('phase4_bob')::uuid,clock_timestamp());
insert into public.profiles(id,display_name) values(md5('phase4_alice')::uuid,'Phase 4 Alice'),(md5('phase4_bob')::uuid,'Phase 4 Bob');
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('phase4_alice')::uuid,'role','authenticated')::text,true);
select is((select count(*)::int from public.exercises where owner_id is null),183,'authenticated users can browse all system entries');
select throws_ok($$insert into public.exercises(name,exercise_type) values('forged system','compound')$$,'42501',null,'users cannot create system exercises');
select is((pg_temp.affected($$update public.exercises set exercise_type='other' where slug='barbell_bench_press'$$)),0,'system type cannot be modified by a regular user');
select is((select exercise_type from public.exercises where slug='barbell_bench_press'),'compound','system type remains compound');
select throws_ok($$insert into public.exercise_movement_patterns(exercise_id,movement_pattern_id,is_primary) select e.id,p.id,false from public.exercises e cross join public.movement_patterns p where e.slug='barbell_bench_press' and p.slug='hip_hinge'$$,'42501',null,'system classifications cannot be inserted by a user');
select is((pg_temp.affected($$delete from public.exercise_equipment where exercise_id=(select id from public.exercises where slug='barbell_bench_press')$$)),0,'system equipment cannot be removed');
select throws_ok($$select public.save_custom_exercise((select id from public.exercises where slug='barbell_bench_press'),'Forged','isolation',(select id from public.movement_patterns where slug='squat'),'{}',array[(select id from public.muscle_groups where slug='quadriceps')],'{}',array[(select id from public.equipment_types where slug='none')],'')$$,'42501',null,'invoker editor cannot update a system exercise');
select lives_ok($$select set_config('body_test.exercise_id',public.save_custom_exercise(null,'Private squat','compound',(select id from public.movement_patterns where slug='squat'),'{}',array[(select id from public.muscle_groups where slug='quadriceps')],array[(select id from public.muscle_groups where slug='glutes')],array[(select id from public.equipment_types where slug='none')],'A private exercise')::text,true)$$,'owner creates a complete custom exercise atomically');
select is((select exercise_type from public.exercises where id=current_setting('body_test.exercise_id')::uuid),'compound','custom exercise retains compound classification');
select ok((select owner_id=auth.uid() from public.exercises where id=current_setting('body_test.exercise_id')::uuid),'creator is the verified owner');
select is((select count(*)::int from public.exercise_movement_patterns where exercise_id=current_setting('body_test.exercise_id')::uuid and is_primary),1,'custom has one primary pattern');
-- Inject a transactional test-only failure after the row and pattern/muscle edits.
reset role;
create function pg_temp.reject_equipment() returns trigger language plpgsql security invoker as $$
begin raise exception 'Synthetic equipment failure' using errcode='23514'; end; $$;
create trigger phase4_test_failure before insert on public.exercise_equipment for each row execute function pg_temp.reject_equipment();
set local role authenticated;
select throws_ok($$select public.save_custom_exercise(current_setting('body_test.exercise_id')::uuid,'Must roll back','isolation',(select id from public.movement_patterns where slug='knee_extension'),'{}',array[(select id from public.muscle_groups where slug='quadriceps')],'{}',array[(select id from public.equipment_types where slug='resistance_band')],'')$$,'23514','Synthetic equipment failure','mid-save failure rolls back the whole edit');
select is((select name from public.exercises where id=current_setting('body_test.exercise_id')::uuid),'Private squat','failed transaction preserves old name');
select is((select exercise_type from public.exercises where id=current_setting('body_test.exercise_id')::uuid),'compound','failed transaction preserves old type');
select ok(exists(select 1 from public.exercise_movement_patterns x join public.movement_patterns p on p.id=x.movement_pattern_id where x.exercise_id=current_setting('body_test.exercise_id')::uuid and x.is_primary and p.slug='squat'),'failed transaction restores primary pattern');
select ok(exists(select 1 from public.exercise_equipment x join public.equipment_types e on e.id=x.equipment_type_id where x.exercise_id=current_setting('body_test.exercise_id')::uuid and e.slug='none'),'failed transaction restores equipment links');
reset role;
drop trigger phase4_test_failure on public.exercise_equipment;
set local role authenticated;
select throws_ok($$select public.save_custom_exercise(current_setting('body_test.exercise_id')::uuid,'Bad edit','unrestricted',(select id from public.movement_patterns where slug='squat'),'{}',array[(select id from public.muscle_groups where slug='quadriceps')],'{}',array[(select id from public.equipment_types where slug='none')],'')$$,'22023',null,'custom type validation rejects unrestricted values');
select throws_ok($$select public.save_custom_exercise(current_setting('body_test.exercise_id')::uuid,'Bad edit','isolation',(select id from public.movement_patterns where slug='squat'),'{}',array[(select id from public.muscle_groups where slug='quadriceps')],'{}',array[(select id from public.equipment_types where slug='none'),(select id from public.equipment_types where slug='dumbbell')],'')$$,'22023',null,'None cannot be combined with equipment alternatives');
select is((select name from public.exercises where id=current_setting('body_test.exercise_id')::uuid),'Private squat','failed edit preserves the prior exercise');
select lives_ok($$select public.save_custom_exercise(current_setting('body_test.exercise_id')::uuid,'Private leg extension','isolation',(select id from public.movement_patterns where slug='knee_extension'),'{}',array[(select id from public.muscle_groups where slug='quadriceps')],'{}',array[(select id from public.equipment_types where slug='resistance_band')],'Updated')$$,'owner can edit and replace classifications');
select is((select exercise_type from public.exercises where id=current_setting('body_test.exercise_id')::uuid),'isolation','custom edit retains selected isolation classification');
select is((select count(*)::int from public.exercise_muscles where exercise_id=current_setting('body_test.exercise_id')::uuid and muscle_role='secondary'),0,'old secondary links are replaced, not accumulated');
select throws_ok($$update public.exercises set exercise_type='invalid' where id=current_setting('body_test.exercise_id')::uuid$$,'23514',null,'direct writes also enforce constrained type');
select set_config('request.jwt.claims',json_build_object('sub',md5('phase4_bob')::uuid,'role','authenticated')::text,true);
select is((select count(*)::int from public.exercises where id=current_setting('body_test.exercise_id')::uuid),0,'another user cannot read a private exercise');
select is((pg_temp.affected($$update public.exercises set exercise_type='other' where id=current_setting('body_test.exercise_id')::uuid$$)),0,'another user cannot edit type');
select is((pg_temp.affected($$delete from public.exercise_movement_patterns where exercise_id=current_setting('body_test.exercise_id')::uuid$$)),0,'another user cannot delete private classifications');
select throws_ok($$insert into public.exercise_movement_patterns(exercise_id,movement_pattern_id) select current_setting('body_test.exercise_id')::uuid,id from public.movement_patterns where slug='hip_hinge'$$,'42501',null,'another user cannot insert private classifications');
select throws_ok($$select public.save_custom_exercise(current_setting('body_test.exercise_id')::uuid,'Stolen','compound',(select id from public.movement_patterns where slug='squat'),'{}',array[(select id from public.muscle_groups where slug='quadriceps')],'{}',array[(select id from public.equipment_types where slug='none')],'')$$,'42501',null,'another user cannot use the atomic editor on a private exercise');
select is((select count(*)::int from public.exercise_muscles where exercise_id=current_setting('body_test.exercise_id')::uuid),0,'another user cannot read private classifications');
select set_config('request.jwt.claims',json_build_object('sub',md5('phase4_alice')::uuid,'role','authenticated')::text,true);
insert into public.user_exercise_preferences(owner_id,exercise_id,is_favorite,preference) values(auth.uid(),current_setting('body_test.exercise_id')::uuid,true,'preferred');
select lives_ok($$update public.user_exercise_preferences set is_favorite=false where owner_id=auth.uid() and exercise_id=current_setting('body_test.exercise_id')::uuid$$,'owner can unmark a favorite without losing preference');
select is((select preference from public.user_exercise_preferences where owner_id=auth.uid() and exercise_id=current_setting('body_test.exercise_id')::uuid),'preferred','favorite updates preserve independent preference');
insert into public.workout_sessions(id,owner_id,name) values(md5('phase4_session')::uuid,auth.uid(),'Synthetic history');
insert into public.workout_exercises(id,owner_id,workout_session_id,position,exercise_id,exercise_name_snapshot) values(md5('phase4_performed')::uuid,auth.uid(),md5('phase4_session')::uuid,1,current_setting('body_test.exercise_id')::uuid,'Original snapshot');
update public.exercises set archived_at=now() where id=current_setting('body_test.exercise_id')::uuid;
select is((select count(*)::int from public.workout_exercises where id=md5('phase4_performed')::uuid),1,'archiving preserves historical references');
select is((select exercise_name_snapshot from public.workout_exercises where id=md5('phase4_performed')::uuid),'Original snapshot','archiving preserves historical snapshots');
select is((select exercise_type from public.exercises where id=current_setting('body_test.exercise_id')::uuid),'isolation','archive preserves classification');
select throws_ok($$select public.save_custom_exercise(current_setting('body_test.exercise_id')::uuid,'Revived','compound',(select id from public.movement_patterns where slug='squat'),'{}',array[(select id from public.muscle_groups where slug='quadriceps')],'{}',array[(select id from public.equipment_types where slug='none')],'')$$,'42501',null,'editor cannot silently revive an archived exercise');
select * from finish();
rollback;
